#include <stdio.h>
#include <string.h>
#include <stdbool.h>

#define MAX_WORDS 1000
#define MAX_LEN 16
#define GRID_SIZE 4

char grid[GRID_SIZE][GRID_SIZE];
int n_words;
char words[MAX_WORDS][MAX_LEN + 1];
int scores[MAX_WORDS];
int T;

int dr[] = {-1, -1, -1, 0, 0, 1, 1, 1};
int dc[] = {-1, 0, 1, -1, 1, -1, 0, 1};

bool dfs(int r, int c, int idx, char *word, bool visited[GRID_SIZE][GRID_SIZE]) {
    if (word[idx] == '\0') return true;
    if (r < 0 || r >= GRID_SIZE || c < 0 || c >= GRID_SIZE) return false;
    if (visited[r][c]) return false;
    if (grid[r][c] != word[idx]) return false;

    visited[r][c] = true;
    for (int d = 0; d < 8; d++) {
        if (dfs(r + dr[d], c + dc[d], idx + 1, word, visited)) {
            visited[r][c] = false;
            return true;
        }
    }
    visited[r][c] = false;
    return false;
}

bool can_form(char *word) {
    bool visited[GRID_SIZE][GRID_SIZE] = {false};
    for (int r = 0; r < GRID_SIZE; r++) {
        for (int c = 0; c < GRID_SIZE; c++) {
            if (grid[r][c] == word[0]) {
                if (dfs(r, c, 0, word, visited))
                    return true;
            }
        }
    }
    return false;
}

int main() {
    // Read grid
    for (int i = 0; i < GRID_SIZE; i++) {
        for (int j = 0; j < GRID_SIZE; j++) {
            scanf(" %c", &grid[i][j]);
        }
    }

    // Read dictionary
    scanf("%d", &n_words);
    for (int i = 0; i < n_words; i++) {
        scanf("%s %d", words[i], &scores[i]);
    }

    scanf("%d", &T);

    bool possible[MAX_WORDS] = {false};
    int time_cost[MAX_WORDS];
    int score_val[MAX_WORDS];
    int m = 0;

    for (int i = 0; i < n_words; i++) {
        if (can_form(words[i])) {
            int len = strlen(words[i]);
            if (len <= T) {
                possible[m] = true;
                time_cost[m] = len;
                score_val[m] = scores[i];
                m++;
            }
        }
    }

    // DP over time
    int dp[T + 1];
    memset(dp, -1, sizeof(dp));
    dp[0] = 0;

    for (int i = 0; i < m; i++) {
        int cost = time_cost[i];
        int val = score_val[i];
        for (int t = T; t >= cost; t--) {
            if (dp[t - cost] != -1) {
                if (dp[t] < dp[t - cost] + val)
                    dp[t] = dp[t - cost] + val;
            }
        }
    }

    int ans = 0;
    for (int t = 0; t <= T; t++) {
        if (dp[t] > ans) ans = dp[t];
    }

    printf("%d\n", ans);
    return 0;
}

