#define MAX_LEN 32
#define BOARD_N 16
#define MAX_STATES 70000
#define INF 1000000000

typedef struct TrieNode {
    int child[26];
    int word_id;
} TrieNode;

typedef struct {
    char s[MAX_LEN];
    int score;
    int len;
} DictWord;

typedef struct {
    int word_id;
    int score;
    int time_cost;
    unsigned short mask;
} FoundWord;

static TrieNode trie[200000];
static int trie_sz = 1;

static DictWord dict[MAX_WORDS];
static int W;

static char board[16];
static int neigh[16][8];
static int neigh_cnt[16];

static FoundWord found[5000];
static int found_cnt;

static int best_time_for_word[MAX_WORDS];
static unsigned short best_mask_for_word[MAX_WORDS];

static int memo[1 << 16];

static void trie_init() {
    trie_sz = 1;
    memset(&trie[0], 0, sizeof(TrieNode));
    trie[0].word_id = -1;
}

static int trie_new_node() {
    memset(&trie[trie_sz], 0, sizeof(TrieNode));
    trie[trie_sz].word_id = -1;
    return trie_sz++;
}

static void trie_insert(const char *s, int id) {
    int cur = 0;
    for (int i = 0; s[i]; i++) {
        int c = s[i] - 'A';
        if (trie[cur].child[c] == 0) {
            trie[cur].child[c] = trie_new_node();
        }
        cur = trie[cur].child[c];
    }
    trie[cur].word_id = id;
}

static void build_neighbors() {
    for (int i = 0; i < 16; i++) {
        int r = i / 4, c = i % 4;
        neigh_cnt[i] = 0;
        for (int dr = -1; dr <= 1; dr++) {
            for (int dc = -1; dc <= 1; dc++) {
                if (dr == 0 && dc == 0) continue;
                int nr = r + dr, nc = c + dc;
                if (nr >= 0 && nr < 4 && nc >= 0 && nc < 4) {
                    neigh[i][neigh_cnt[i]++] = nr * 4 + nc;
                }
            }
        }
    }
}

static void dfs_board(int pos, int trie_node, unsigned short used_mask, int depth) {
    int wid = trie[trie_node].word_id;
    if (wid >= 0) {
        int time_cost = depth - 1;
        if (time_cost < best_time_for_word[wid]) {
            best_time_for_word[wid] = time_cost;
            best_mask_for_word[wid] = used_mask;
        }
    }

    for (int k = 0; k < neigh_cnt[pos]; k++) {
        int np = neigh[pos][k];
        if (used_mask & (1u << np)) continue;
        int ch = board[np] - 'A';
        int nxt = trie[trie_node].child[ch];
        if (!nxt) continue;
        dfs_board(np, nxt, used_mask | (1u << np), depth + 1);
    }
}

static int solve_dp(int mask) {
    int *res = &memo[mask];
    if (*res != -1) return *res;
    int best = 0;
    for (int i = 0; i < found_cnt; i++) {
        if ((mask & found[i].mask) == 0) {
            int cand = found[i].score + solve_dp(mask | found[i].mask);
            if (cand > best) best = cand;
        }
    }
    *res = best;
    return best;
}

int main() {
    int T;
    if (scanf("%d", &T) != 1) return 0;
    if (scanf("%d", &W) != 1) return 0;

    trie_init();

    for (int i = 0; i < W; i++) {
        scanf("%s %d", dict[i].s, &dict[i].score);
        dict[i].len = (int)strlen(dict[i].s);
        for (int j = 0; dict[i].s[j]; j++) dict[i].s[j] = (char)toupper(dict[i].s[j]);
        trie_insert(dict[i].s, i);
    }

    for (int i = 0; i < 16; i++) {
        char tmp[8];
        scanf("%s", tmp);
        board[i] = (char)toupper(tmp[0]);
    }

    build_neighbors();

    for (int i = 0; i < W; i++) {
        best_time_for_word[i] = INF;
        best_mask_for_word[i] = 0;
    }

    for (int i = 0; i < 16; i++) {
        int ch = board[i] - 'A';
        int nxt = trie[0].child[ch];
        if (nxt) {
            dfs_board(i, nxt, (unsigned short)(1u << i), 1);
        }
    }

    found_cnt = 0;
    for (int i = 0; i < W; i++) {
        if (best_time_for_word[i] <= T) {
            found[found_cnt].word_id = i;
            found[found_cnt].score = dict[i].score;
            found[found_cnt].time_cost = best_time_for_word[i];
            found[found_cnt].mask = best_mask_for_word[i];
            found_cnt++;
        }
    }

    /* Time limit handling:
       tracing a word of length L takes L-1 moves.
       Since words must be unique and cannot reuse already occupied cells
       in this formulation, total usable cells are represented by masks.
       We additionally filter by individual time <= T. If the original task
       intended total time budget across all words, use knapsack on top;
       here we maximize score over non-overlapping words and per-word time bound.
    */

    for (int i = 0; i < (1 << 16); i++) memo[i] = -1;
    memo[(1 << 16) - 1] = 0;

    int ans = solve_dp(0);
    printf("%d\n", ans);
    return 0;
}

