#include <bits/stdc++.h>
using namespace std;

/*
We have a 4x4 board of uppercase letters and a dictionary of words with scores.
A word can be traced if:
- consecutive letters are on neighboring cells (8 directions),
- no cell is used more than once in the same word trace.

Tracing a found word costs time equal to its length.
Each dictionary word may be scored at most once.
Goal: maximize total score within total time T.

Approach:
1) Build a trie of dictionary words, storing score at terminal nodes.
2) Enumerate all distinct dictionary words that can be formed on the board using DFS + trie pruning.
3) This gives items (time = word length, value = score), each usable once.
4) Run 0/1 knapsack for capacity T.

This is efficient because the board is only 4x4, and trie pruning avoids exploring impossible prefixes.
*/

struct TrieNode {
    int nxt[26];
    int score;
    int len;
    bool terminal;
    TrieNode() {
        memset(nxt, -1, sizeof(nxt));
        score = 0;
        len = 0;
        terminal = false;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, T;
    cin >> N >> T;

    vector<TrieNode> trie(1);

    auto addWord = [&](const string& s, int sc) {
        int cur = 0;
        for (char ch : s) {
            int c = ch - 'A';
            if (trie[cur].nxt[c] == -1) {
                trie[cur].nxt[c] = (int)trie.size();
                trie.emplace_back();
            }
            cur = trie[cur].nxt[c];
        }
        trie[cur].terminal = true;
        trie[cur].score = sc;
        trie[cur].len = (int)s.size();
    };

    for (int i = 0; i < N; ++i) {
        string w;
        int s;
        cin >> w >> s;
        addWord(w, s);
    }

    vector<string> board(4);
    for (int i = 0; i < 4; ++i) cin >> board[i];

    vector<int> foundNodes;
    vector<char> found(trie.size(), 0);

    int dr[8] = {-1,-1,-1,0,0,1,1,1};
    int dc[8] = {-1,0,1,-1,1,-1,0,1};

    function<void(int,int,int,int)> dfs = [&](int r, int c, int node, int mask) {
        if (trie[node].terminal && !found[node]) {
            found[node] = 1;
            foundNodes.push_back(node);
        }

        for (int k = 0; k < 8; ++k) {
            int nr = r + dr[k], nc = c + dc[k];
            if (nr < 0 || nr >= 4 || nc < 0 || nc >= 4) continue;
            int bit = nr * 4 + nc;
            if (mask & (1 << bit)) continue;
            int ch = board[nr][nc] - 'A';
            int nxt = trie[node].nxt[ch];
            if (nxt == -1) continue;
            dfs(nr, nc, nxt, mask | (1 << bit));
        }
    };

    for (int r = 0; r < 4; ++r) {
        for (int c = 0; c < 4; ++c) {
            int ch = board[r][c] - 'A';
            int nxt = trie[0].nxt[ch];
            if (nxt != -1) {
                int bit = r * 4 + c;
                dfs(r, c, nxt, 1 << bit);
            }
        }
    }

    vector<int> dp(T + 1, 0);
    for (int node : foundNodes) {
        int w = trie[node].len;
        int v = trie[node].score;
        if (w > T) continue;
        for (int t = T; t >= w; --t) {
            dp[t] = max(dp[t], dp[t - w] + v);
        }
    }

    cout << *max_element(dp.begin(), dp.end()) << '\n';
    return 0;
}

