from collections import defaultdict

def solve():
    input_data = sys.stdin.read().split('\n')
    idx = 0

    # Read 4x4 grid
    grid = []
    for i in range(4):
        row = input_data[idx].strip()
        grid.append(list(row))
        idx += 1

    # Read T
    T = int(input_data[idx].strip())
    idx += 1

    # Read dictionary: number of words, then word score pairs
    n = int(input_data[idx].strip())
    idx += 1

    dictionary = {}
    for i in range(n):
        parts = input_data[idx].strip().split()
        word, score = parts[0], int(parts[1])
        dictionary[word] = score
        idx += 1

    # Find all traceable words using DFS (Boggle)
    def can_trace(word):
        rows, cols = 4, 4
        def dfs(r, c, pos, visited):
            if pos == len(word):
                return True
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if dr == 0 and dc == 0:
                        continue
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols and (nr, nc) not in visited:
                        if grid[nr][nc] == word[pos]:
                            visited.add((nr, nc))
                            if dfs(nr, nc, pos + 1, visited):
                                return True
                            visited.remove((nr, nc))
            return False

        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == word[0]:
                    visited = {(r, c)}
                    if len(word) == 1 or dfs(r, c, 1, visited):
                        return True
        return False

    # Find valid words
    valid_words = []
    for word, score in dictionary.items():
        if can_trace(word):
            valid_words.append((len(word), score, word))

    # Knapsack: maximize score with total time <= T
    # Each word can be used at most once
    dp = [0] * (T + 1)
    for time, score, word in valid_words:
        for t in range(T, time - 1, -1):
            dp[t] = max(dp[t], dp[t - time] + score)

    print(dp[T])

