            for (int t = T; t >= w.length; t--) {
                dp[t] = Math.max(dp[t], dp[t - w.length] + w.score);
            }
        }

        System.out.println(dp[T]);
    }

    static void dfs(char[][] grid, TrieNode root, boolean[][] visited,
                    int x, int y, StringBuilder current, Set<String> foundWords) {
        char c = grid[x][y];
        int idx = c - 'A';
        if (root.children[idx] == null) return;

        TrieNode next = root.children[idx];
        current.append(c);
        if (next.isWord) {
            foundWords.add(current.toString());
        }

        visited[x][y] = true;
        for (int d = 0; d < 8; d++) {
            int nx = x + dx[d];
            int ny = y + dy[d];
            if (nx >= 0 && nx < 4 && ny >= 0 && ny < 4 && !visited[nx][ny]) {
                dfs(grid, next, visited, nx, ny, current, foundWords);
            }
        }
        visited[x][y] = false;
        current.deleteCharAt(current.length() - 1);
    }

    static int getScore(TrieNode root, String word) {
        TrieNode node = root;
        for (char c : word.toCharArray()) {
            node = node.children[c - 'A'];
        }
        return node.score;
    }

    static class Word {
        String word;
        int score, length;
        Word(String w, int s, int l) {
            word = w;
            score = s;
            length = l;
        }
    }
}

